int warpMode(String name){const std::map<String,int> modes={{"kBendPos",10},{"kBendNeg",11},{"kBendPosNeg",12},{"kSync",2},{"kPD_OSC",8},{"kPD_OSC2",9},{"kPD_SUB",44},{"kPD_NOISE",61},{"kFM_OSC",39},{"kFM_OSC2",40},{"kFM_SUB",41},{"kFM_NOISE",60},{"kRM_OSC",54},{"kRM_OSC2",55},{"kRM_FILT2",59},{"kDistDiode1",28},{"kDistSoftSat",38},{"kDistSoftClip",26},{"kFilterLPF",5},{"kFilterHPF",6},{"kRemap_1",19},{"kRemap_2",20}};auto it=modes.find(name);return it==modes.end()?0:it->second;}

