std::shared_ptr<SampleData> SampleData::decode(const MemoryBlock& bytes,String name,String& error){AudioFormatManager fm;fm.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(fm.createReaderFor(std::make_unique<MemoryInputStream>(bytes,false)));if(!reader||reader->lengthInSamples<2||reader->lengthInSamples>192000*60||reader->sampleRate<8000||reader->sampleRate>384000){error="Unsupported or oversized sample: "+name;return {};}auto s=std::make_shared<SampleData>();s->name=name;s->rate=reader->sampleRate;s->original=bytes;s->audio.setSize(2,(int)reader->lengthInSamples);if(!reader->read(&s->audio,0,s->audio.getNumSamples(),0,true,true)){error="Sample read failed: "+name;return {};}if(reader->numChannels==1)s->audio.copyFrom(1,0,s->audio,0,0,s->audio.getNumSamples());for(int c=0;c<2;++c)for(int i=0;i<s->audio.getNumSamples();++i)if(!std::isfinite(s->audio.getSample(c,i)))s->audio.setSample(c,i,0);return s;}
float SampleData::read(double pos,int ch,bool loop)const noexcept{int len=audio.getNumSamples();if(loop){pos=std::fmod(pos,(double)len);if(pos<0)pos+=len;}else if(pos<0||pos>=len)return 0;int i=(int)pos;float t=(float)(pos-i);return audio.getSample(jmin(1,ch),i)*(1-t)+audio.getSample(jmin(1,ch),loop?(i+1)%len:jmin(i+1,len-1))*t;}
